// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 mintAmount, uint256 burnAmount) public {
        vm.assume(mintAmount > 0);
        vm.assume(burnAmount > 0 && burnAmount <= mintAmount);
        vm.prank(c.owner());
        c.mintToken(address(this), mintAmount);
        uint256 totalSupplyBefore = c.totalSupply();
        vm.prank(c.owner());
        c.burn(burnAmount);
        uint256 totalSupplyAfter = c.totalSupply();
        assertTrue(totalSupplyAfter == totalSupplyBefore - burnAmount);
    }
}

